window.VZOROVA_ZKOUSKA = {"sada":"cvicna-2","oficialni":false,"otazky":[{"id":"UC-1-26","n":1,"lo":"FL-1.1.1","k":"K1","k3":true,"vyber":1,"q":"Který z následujících je typickým cílem testování?","m":["Zajištění požadovaného pokrytí testovaného objektu","Soustředění defektů do malého počtu komponent","Nalezení a odstranění příčin selhání v kódu","Provedení kompletního testování všech kombinací vstupů"],"ok":[0],"vys":{"a":"Je správně. Zajištění požadovaného pokrytí testovaného objektu je jedním z typických cílů testování.","b":"Není správně. Shlukování defektů je princip testování popisující, kde se defekty vyskytují, nikoli cíl.","c":"Není správně. Hledání a odstraňování příčin selhání je ladění, které je samostatnou činností.","d":"Není správně. Kompletní testování není možné s výjimkou triviálních případů."},"obecne":"Sylabus 1.1.1 uvádí mezi typickými cíli testování zajištění požadovaného pokrytí testovaného objektu. Kompletní testování není možné, shlukování defektů je princip testování a ladění je činnost oddělená od testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"}},{"id":"UP-5-08","n":2,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":2,"q":"Které DVĚ z následujících možností NEJLÉPE představují odpovědnosti, které jsou v souladu s týmovým přístupem?","m":["Testeři odpovídají za vývoj testů komponent, které předávají vývojářům k provedení.","Od zástupců byznysu se očekává, že vyberou nástroje, které bude tým během projektu používat.","Od testerů se očekává, že budou spolupracovat se zástupci zákazníka na vytváření akceptačních testů.","Za kvalitu produktu odpovídá celý tým, nejen testeři.","Od vývojářů se očekává, že budou testovat nefunkcionální požadavky (výkonnost, použitelnost, zabezpečení atd.)."],"ok":[2,3],"vys":{"a":"Není správně. Rozdělení úkolů závisí na dovednostech členů týmu; testy komponent obvykle vytvářejí vývojáři.","b":"Není správně. Nástroje vybírá tým společně, nikoli pouze zástupci byznysu.","c":"Je správně. Testeři spolupracují se zástupci byznysu a pomáhají jim vytvořit vhodné akceptační testy.","d":"Je správně. Při týmovém přístupu je každý člen týmu zodpovědný za kvalitu.","e":"Není správně. Nefunkcionální testování není vyhrazeno vývojářům; úkoly přebírá ten, kdo má potřebné dovednosti."},"obecne":"Sylabus 1.5.2: Při týmovém přístupu může každý člen týmu s potřebnými znalostmi a dovednostmi vykonávat jakýkoliv úkol a každý je zodpovědný za kvalitu. Testeři úzce spolupracují se zástupci byznysu, např. na vytvoření vhodných akceptačních testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UC-1-38","n":3,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Tester prováděl testovací případ, v němž měl do vyhledávacího pole zadat název položky „Laptop“. Omylem však zadal hodnotu „labtob“.<\/p><p>Skutečným výsledkem byla zpráva „Pro slovo labtob nebyly nalezeny žádné výsledky, neměli jste na mysli laptop?“<\/p><p>Tester nahlásil defekt s popisem: „Když uživatel vyhledává laptopy, zobrazí se chybová zpráva, místo toho by se měl zobrazit seznam laptopů.“<\/p><p>Co NEJLÉPE popisuje tuto situaci?<\/p>","m":["Tester udělal chybu, jejímž důsledkem je falešně negativní výsledek.","Vývojář udělal chybu při psaní kódu, která vedla k defektu.","Tester udělal chybu, jejímž důsledkem je falešně pozitivní výsledek.","V této situaci žádný problém není, report o defektu je oprávněný."],"ok":[2],"vys":{"a":"Není správně. Falešně negativní výsledek by znamenal, že test neodhalil existující defekt.","b":"Není správně. Aplikace se zachovala správně, v kódu žádný defekt není.","c":"Je správně. Tester nahlásil jako defekt chování, které je správné; jde o falešně pozitivní výsledek způsobený jeho chybou při zadání testovacích dat.","d":"Není správně. Report popisuje neexistující defekt, takže problém existuje."},"obecne":"Sylabus 5.5 uvádí, že ne všechny nahlášené anomálie musí být skutečné defekty, např. falešně pozitivní výsledky testů. Falešně pozitivní výsledek je reportován jako defekt, ačkoli v testovaném objektu žádný defekt není; zde vznikl chybou testera (sylabus 1.2.3: lidé dělají chyby, i testeři).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"UP-4-03","n":4,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Jako manažer testování shromažďujete měření týkající se defektů. Zjistíte, že po prvním testovacím cyklu, který pokryl všechny požadavky, má subsystém C hustotu defektů o 150 % vyšší, než je průměr. Subsystém A má naopak hustotu defektů o 60 % nižší, než je průměr. Jaký závěr pro další testovací cyklus můžete z této skutečnosti NEJLÉPE vyvodit?","m":["<p>Zjištěná hustota defektů neumožňuje vyvodit žádné závěry o rozsahu dalšího testování.<\/p>","<p>Protože jsme v subsystému C již našli mnoho defektů, měli bychom testovací zdroje soustředit na subsystém A.<\/p>","<p>Měli bychom se snažit vyrovnat rozsah testování napříč všemi moduly, abychom všechny subsystémy testovali rovnoměrně.<\/p>","<p>Je pravděpodobné, že subsystém C obsahuje ještě další skryté defekty. Proto musíme subsystém C testovat podrobněji.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Pozorované shluky defektů jsou významným vstupem pro testování založené na rizicích.","b":"Není správně. Vysoký počet nalezených defektů v C nesvědčí o tom, že je již vyčištěný; spíše naopak.","c":"Není správně. Rovnoměrné rozložení úsilí ignoruje zjištěné shluky defektů a riziko.","d":"Je správně. Podle principu shlukování defektů lze v subsystému C s vysokou hustotou defektů očekávat další skryté defekty, proto je vhodné jej testovat podrobněji."},"obecne":"Sylabus 1.3, princip 4 (Shlukování defektů): Většinu defektů obvykle obsahuje malé množství komponent. Předpokládané a skutečně pozorované shluky defektů jsou významným vstupem pro testování založené na rizicích, proto se další testování soustředí na subsystém C.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-6-04","n":5,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je příkladem úlohy, kterou lze provádět jako součást procesu testování?<\/p>","m":["Návrh testovacích dat","Přidělení verze testovanému produktu","Napsání uživatelského scénáře","Analýza a oprava defektu v kódu"],"ok":[0],"vys":{"a":"Je správně. Stanovení požadavků na testovací data je součástí návrhu testů a jejich vytvoření součástí implementace testování.","b":"Není správně. Přidělování verzí položkám je součástí konfiguračního managementu.","c":"Není správně. Na psaní uživatelských scénářů se tester může podílet (plánování vydání), nejde však o činnost procesu testování, ale o tvorbu testovací báze.","d":"Není správně. Diagnostika a oprava defektu jsou součástí ladění, nikoli procesu testování."},"obecne":"Sylabus 1.4.1: Návrh testů zahrnuje mimo jiné stanovení požadavků na testovací data, implementace testování jejich vytvoření. Analýza a oprava defektu je ladění, které podle sylabu 1.1.2 není součástí testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"TR-078","n":6,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývá položka testovacího prostředí, která při integračním testování nahrazuje volanou komponentu, jež ještě není k dispozici?","m":["Testovací listina","Stub","Testovací sada","Testovací procedura"],"ok":[1],"vys":{"a":"Není správně. Testovací listina je pracovní produkt návrhu testů pro průzkumné testování.","b":"Je správně. Stub je položka testovacího prostředí, která simuluje chování chybějící volané komponenty.","c":"Není správně. Testovací sada je skupina testovacích skriptů nebo procedur, ne náhrada komponenty.","d":"Není správně. Testovací procedura je posloupnost testovacích případů, ne náhrada komponenty."},"obecne":"Sylabus 1.4.3: mezi pracovní produkty implementace testování patří položky testovacího prostředí, např. stuby, ovladače (drivery), simulátory a virtualizace služeb. Stub nahrazuje volanou komponentu, která ještě není k dispozici.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"UP-5-06","n":7,"lo":"FL-1.4.5","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje, jak jsou úkoly rozděleny mezi manažera testování a testera?<\/p>","m":["Manažer testování plánuje testovací činnosti a volí normy, které se budou dodržovat, zatímco tester volí nástroje a pravidla pro jejich používání.","Manažer testování plánuje a organizuje testování a specifikuje testovací případy, zatímco tester prioritizuje a provádí testy.","Manažer testování plánuje, monitoruje a řídí testovací činnosti, zatímco tester analyzuje testovací bázi, navrhuje testy a provádí je.","Manažer testování plánuje, monitoruje a řídí testovací činnosti, zatímco tester navrhuje testy a rozhoduje o uvolnění testovaného objektu."],"ok":[2],"vys":{"a":"Není správně. Výběr nástrojů a pravidel pro jejich používání není typickým úkolem testera.","b":"Není správně. Specifikace testovacích případů (návrh testů) je úkolem testera, nikoli manažera testování.","c":"Je správně. Manažer testování se zaměřuje na plánování, monitoring a řízení testování, tester na testovací analýzu, návrh testů, implementaci a provedení testů.","d":"Není správně. O uvolnění testovaného objektu nerozhoduje tester; testování k rozhodnutí poskytuje informace."},"obecne":"Sylabus 1.4.5: Manažer testování má celkovou odpovědnost za proces testování a zaměřuje se na plánování, monitoring a řízení a dokončení testování. Tester odpovídá za inženýrský aspekt testování: testovací analýzu, návrh testů, implementaci testování a provedení testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"}},{"id":"TR-014","n":8,"lo":"FL-1.5.3","k":"K2","k3":true,"vyber":1,"q":"Co je hlavní výhodou nezávislosti testování?","m":["Nezávislé testování vždy zkracuje celkovou dobu trvání projektu","Nezávislý tester nepotřebuje znát doménu ani testovaný systém","Nezávislé testování odstraňuje potřebu provádět revize","Nezávislý tester díky odlišnému pohledu spíše odhalí jiné druhy defektů"],"ok":[3],"vys":{"a":"Není správně. Nezávislí testeři se naopak mohou stát úzkým místem a být viněni ze zpoždění.","b":"Není správně. Nezávislost není náhradou za dobrou znalost systému.","c":"Není správně. Revize jsou samostatnou formou statického testování a nezávislost je nenahrazuje.","d":"Je správně. Nezávislí testeři pravděpodobněji rozpoznají jiné druhy selhání a defektů díky odlišnému zázemí, technickému nadhledu a předsudkům."},"obecne":"Sylabus 1.5.3: Hlavním přínosem nezávislosti testování je, že nezávislí testeři dokážou pravděpodobněji rozpoznat různé druhy selhání a defektů ve srovnání s vývojáři, a to díky odlišnému zázemí, technickému nadhledu a předsudkům (kognitivnímu zkreslení).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.3","nazev":"Nezávislost testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-tri-nezavislost-testovani"}},{"id":"UP-2-09","n":9,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících bodů jsou osvědčenými postupy testování platnými v jakémkoli modelu životního cyklu vývoje softwaru (SDLC)?<\/p><p>I. Zajistit, aby byly v softwaru odhaleny všechny defekty.<\/p><p>II. Ke každé vývojové činnosti existuje odpovídající testovací činnost.<\/p><p>III. Testeři se zapojují do revize pracovních produktů, jakmile jsou k dispozici jejich pracovní verze (drafty).<\/p><p>IV. Každá úroveň testování má své specifické cíle testování.<\/p>","m":["<p>II, III a IV<\/p>","<p>I a II<\/p>","<p>I a III<\/p>","<p>I, III a IV<\/p>"],"ok":[0],"vys":{"a":"Je správně. Body II, III a IV jsou osvědčené postupy platné v každém modelu SDLC.","b":"Není správně. Obsahuje nesprávný bod I a chybí body III a IV.","c":"Není správně. Obsahuje nesprávný bod I a chybí body II a IV.","d":"Není správně. Bod I není osvědčeným postupem – kompletní testování není možné a testování nemůže prokázat nepřítomnost defektů."},"obecne":"Sylabus 2.1.2: osvědčenými postupy nezávislými na modelu SDLC jsou: ke každé vývojové činnosti existuje odpovídající testovací činnost; každá úroveň testování má své specifické cíle; testovací analýza a návrh testů začínají během odpovídající vývojové fáze; testeři se zapojují do revize pracovních produktů, jakmile jsou k dispozici jejich pracovní verze. Bod I je v rozporu s principem, že testování prokazuje přítomnost defektů, nikoli jejich nepřítomnost (kompletní testování není možné).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"UP-2-10","n":10,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje vývoj řízený testy (TDD)?<\/p>","m":["<p>TDD se zaměřuje na vytvoření rozsáhlých návrhových dokumentů před kódováním.<\/p>","<p>TDD začíná psaním testů, které řídí psaní kódu; testy i kód lze pak refaktorovat.<\/p>","<p>TDD se zabývá především testováním uživatelského rozhraní aplikace.<\/p>","<p>TDD spočívá v psaní testů až po napsání kódu, aby byl pokryt veškerý kód.<\/p>"],"ok":[1],"vys":{"a":"Není správně. V TDD je psaní kódu řízeno testovacími případy místo rozsáhlého návrhu softwaru.","b":"Je správně. Nejprve se napíší testy, potom kód, který jim vyhovuje, a následně mohou být testy i kód refaktorovány.","c":"Není správně. TDD se uplatňuje především při testování komponent, ne při testování uživatelského rozhraní.","d":"Není správně. V TDD se testy píší před kódem, nikoli po něm."},"obecne":"Sylabus 2.1.3: ve vývoji řízeném testy (TDD) je psaní kódu řízeno testovacími případy (místo rozsáhlého návrhu softwaru). Nejprve se napíší testy, poté kód tak, aby testům vyhovoval, a následně mohou (ale nemusí) být testy i kód refaktorovány.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"TR-075","n":11,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"Retrospektiva odhalila, že nejasné požadavky opakovaně vedly k pozdnímu nalezení defektů. Které opatření NEJLÉPE podpoří přístup shift left v příštím sprintu?","m":["Zrušit revize požadavků, aby se ušetřil čas","Posílit tým o další testery na konci sprintu","Zapojit testery do revizí uživatelských scénářů před implementací","Přesunout většinu testování až po nasazení do produkce"],"ok":[2],"vys":{"a":"Není správně. Zrušení revizí by problém s nejasnými požadavky ještě zhoršilo.","b":"Není správně. Více testerů na konci sprintu testování neposouvá dříve.","c":"Je správně. Revize specifikace z pohledu testování je typickým příkladem přístupu shift left.","d":"Není správně. Jde o opak přístupu shift left."},"obecne":"Sylabus 2.1.5: Shift left znamená provádět testování v SDLC dříve. Příkladem je revize specifikace z pohledu testování, díky níž lze nejasnosti a defekty v požadavcích odhalit ještě před implementací.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"TR-017","n":12,"lo":"FL-2.1.1","k":"K2","k3":true,"vyber":1,"q":"Který z následujících je příkladem sekvenčního modelu vývoje softwaru?","m":["Extrémní programování (XP)","Scrum","Kanban","Vodopádový model"],"ok":[3],"vys":{"a":"Není správně. Extrémní programování (XP) je agilní vývojová metoda s krátkými iteracemi.","b":"Není správně. Scrum je agilní rámec založený na iterativním a inkrementálním vývoji.","c":"Není správně. Kanban je agilní metoda řízení toku práce, nikoli sekvenční model vývoje.","d":"Je správně. Vodopádový model je spolu s V-modelem typickým příkladem sekvenčního modelu vývoje."},"obecne":"Sylabus 2.1.1: mezi modely SDLC patří sekvenční modely vývoje (např. vodopádový model, V-model), iterativní a inkrementální modely. Scrum, Kanban a extrémní programování (XP) sylabus uvádí jako vývojové metody a agilní postupy, které se používají v iterativním a inkrementálním vývoji.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"}},{"id":"UC-2-21","n":13,"lo":"FL-2.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Software, na kterém pracujete jako tester, bude převeden z desktopové aplikace na webovou. Jaký typ testování budete NEJPRAVDĚPODOBNĚJI provádět?<\/p>","m":["<p>Testování údržby<\/p>","<p>Testování napříč prohlížeči<\/p>","<p>Konfirmační testování<\/p>","<p>Testování uživatelského rozhraní<\/p>"],"ok":[0],"vys":{"a":"Je správně. Migrace provozního prostředí z jedné platformy na jinou je spouštěčem testování údržby.","b":"Není správně. Testování v různých prohlížečích může být součástí, ale nevystihuje situaci migrace provozovaného systému.","c":"Není správně. Konfirmační testování ověřuje opravu konkrétního defektu, o kterou zde nejde.","d":"Není správně. Testování uživatelského rozhraní může být součástí, ale nevystihuje situaci migrace provozovaného systému."},"obecne":"Sylabus 2.3: spouštěči testování údržby jsou úpravy (plánovaná vylepšení, opravné změny, hotfixy), aktualizace nebo migrace provozního prostředí (např. z jedné platformy na jinou) a vyřazení aplikace z provozu, kdy může být vhodné testovat archivaci dat a procesy jejich obnovení a načtení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.3","nazev":"Testování údržby","href":"kapitola-2/vyklad.html#cast-dva-tecka-tri-testovani-udrzby"}},{"id":"UC-2-05","n":14,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"<p>Narazíte na selhání, při kterém si dva vzájemně spolupracující moduly nesprávně předávají data. Ve které úrovni testování by takové selhání bylo NEJPRAVDĚPODOBNĚJI odhaleno?<\/p>","m":["<p>Testování komponent<\/p>","<p>Integrační testování komponent<\/p>","<p>Systémové testování<\/p>","<p>Systémové integrační testování<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testování komponent se zaměřuje na izolované komponenty, ne na jejich vzájemnou komunikaci.","b":"Je správně. Integrační testování komponent se zaměřuje na rozhraní a interakce mezi komponentami.","c":"Není správně. Systémové testování se zaměřuje na celkové chování celého systému.","d":"Není správně. Systémové integrační testování se zaměřuje na rozhraní s jinými systémy a externími službami, ne mezi moduly jednoho systému."},"obecne":"Sylabus 2.2.1: integrační testování komponent se zaměřuje na testování rozhraní a interakcí mezi komponentami a silně závisí na zvolené integrační strategii (např. zdola nahoru, shora dolů, velký třesk). Systémové integrační testování naopak testuje rozhraní mezi testovaným systémem a dalšími systémy.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"UP-6-15","n":15,"lo":"FL-3.1.1","k":"K1","k3":true,"vyber":1,"q":"<p>Na který z následujících pracovních produktů lze použít statické testování, aby se ověřilo dodržování norem a směrnic?<\/p>","m":["<p>Zátěž systému při stresovém testu<\/p>","<p>Použitelnost uživatelského rozhraní za provozu<\/p>","<p>Zdrojový kód softwaru<\/p>","<p>Výsledky provádění testů za běhu<\/p>"],"ok":[2],"vys":{"a":"Není správně. Chování pod zátěží se posuzuje dynamickým (stresovým) testováním.","b":"Není správně. Použitelnost za provozu se hodnotí dynamickým testováním s uživateli.","c":"Je správně. Statická analýza i revize kódu odhalí odchylky od norem, např. od konvencí pro programování.","d":"Není správně. Výsledky provádění testů vznikají až dynamickým testováním."},"obecne":"Sylabus 3.1.1 a 3.1.3: zdrojový kód je typickým pracovním produktem statického testování a odchylky od norem (např. nedodržování konvencí pro programování) patří mezi defekty, které se snáze odhalí staticky.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.1","nazev":"Pracovní produkty, které mohou být prověřeny statickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-jedna-pracovni-produkty-ktere-mohou-byt-provereny-statickym-testovanim"}},{"id":"UC-3-28","n":16,"lo":"FL-3.2.5","k":"K1","k3":true,"vyber":1,"q":"<p>Který z následujících faktorů <strong>NENÍ<\/strong> faktorem úspěchu revizí?<\/p>","m":["<p>Definování jasných cílů a měřitelných výstupních kritérií.<\/p>","<p>Provádění revizí po malých částech.<\/p>","<p>Poskytování zpětné vazby z revizí zainteresovaným stranám a autorům.<\/p>","<p>Hodnocení výkonu účastníků během revize.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Jasné cíle a měřitelná výstupní kritéria jsou faktorem úspěchu.","b":"Není správně. Revize po malých částech pomáhá revidujícím udržet koncentraci.","c":"Není správně. Zpětná vazba zainteresovaným stranám a autorům je faktorem úspěchu.","d":"Je správně. Hodnocení účastníků by nikdy nemělo být cílem revize; hodnotí se pracovní produkt."},"obecne":"Sylabus 3.2.5: faktory úspěchu zahrnují jasné cíle a měřitelná výstupní kritéria, revize po malých částech a zpětnou vazbu zainteresovaným stranám a autorům. Hodnocení účastníků by nikdy nemělo být cílem revize.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"}},{"id":"UP-5-16","n":17,"lo":"FL-3.1.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení SPRÁVNĚ vystihuje hodnotu statického testování?<\/p>","m":["<p>Od doby, kdy používáme statickou analýzu, nacházíme defekty v kódu, které by samotné dynamické testování nemuselo odhalit.<\/p>","<p>Díky statickému testování máme levnější management defektů, protože defekty lze snadno odstraňovat později v SDLC.<\/p>","<p>Od doby, kdy vyžadujeme statickou analýzu, ubylo opomenutých požadavků a zlepšila se komunikace mezi testery a vývojáři.<\/p>","<p>Zavedením revizí jsme zjistili, že se zvýšila jak kvalita specifikací, tak čas potřebný pro vývoj a testování.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Statická analýza může odhalit defekty v kódu, které dynamickým testováním nelze zjistit nebo se zjišťují obtížně.","b":"Není správně. Defekty se naopak snáze a levněji odstraňují v raných fázích SDLC.","c":"Není správně. Opomenuté požadavky a lepší komunikaci přinášejí revize, nikoli statická analýza.","d":"Není správně. Revize zvyšují kvalitu specifikací, celková pracnost vývoje a testování se však díky nim obvykle snižuje."},"obecne":"Sylabus 3.1.2: statické testování může odhalit defekty, které nelze zjistit dynamickým testováním (např. nedosažitelný kód), a některé defekty v kódu odhalí statická analýza mnohem efektivněji než dynamické testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"}},{"id":"UC-3-16","n":18,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Jaký je hlavní rozdíl mezi předvedením (walkthrough) a inspekcí?<\/p>","m":["<p>Při inspekci autor není přítomen, zatímco při předvedení ano<\/p>","<p>Předvedení vede autor, zatímco inspekci autor vést nemůže<\/p>","<p>Inspekci vede moderátor, zatímco předvedení nemá žádného vedoucího<\/p>","<p>Inspekci vede autor, zatímco předvedení vede vyškolený moderátor<\/p>"],"ok":[1],"vys":{"a":"Není správně. Autor se inspekce účastní, jen ji nemůže vést.","b":"Je správně. Předvedení vede autor, zatímco při inspekci nemůže autor vystupovat jako vedoucí revize ani zapisovatel.","c":"Není správně. Předvedení vede autor, vedoucího tedy má.","d":"Není správně. Je to naopak – předvedení vede autor a inspekci autor vést nemůže."},"obecne":"Sylabus 3.2.4: předvedení je vedené autorem; u inspekce nemůže autor vystupovat jako vedoucí revize nebo zapisovatel.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UP-6-19","n":19,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Tester analyzuje uživatelské scénáře jako testovací bázi. Odvodí z nich testovací případy pomocí testování přechodů stavů, provede je a změří dosažené pokrytí platných přechodů. Jde o příklad použití které kategorie technik testování?<\/p>","m":["<p>Techniky testování bílé skříňky<\/p>","<p>Techniky testování založené na zkušenostech<\/p>","<p>Techniky testování černé skříňky<\/p>","<p>Přístupy k testování založené na spolupráci<\/p>"],"ok":[2],"vys":{"a":"Není správně. Pokrytí se měří na stavovém modelu odvozeném ze specifikace, ne na struktuře kódu.","b":"Není správně. Testy jsou odvozeny systematicky z modelu, ne ze znalostí a intuice testera.","c":"Je správně. Testování přechodů stavů je technika černé skříňky – vychází ze specifikovaného chování (modelu), ne z kódu.","d":"Není správně. Uživatelské scénáře zde slouží jen jako testovací báze; použitou technikou je testování přechodů stavů."},"obecne":"<p>Sylabus 4.1 a 4.2: Testování přechodů stavů patří mezi techniky testování černé skříňky, které jsou založeny na analýze specifikovaného chování testovaného objektu bez informací o jeho vnitřní struktuře.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UP-2-20","n":20,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Automatická klimatizace zapne topení, když teplota klesne pod 17 °C, a chlazení, když teplota překročí 26 °C. Klimatizace je určena pro provoz při teplotách od −10 °C do +40 °C; teplota se měří v celých stupních. Která z následujících sad hodnot pokrývá všechny třídy ekvivalence (platné i neplatné) s NEJMENŠÍM počtem hodnot?<\/p>","m":["−11, 18, 51","−1, 12, 18, 27","−11, −1, 12, 18, 27, 51","−11, −1, 18, 27, 51"],"ok":[3],"vys":{"a":"Není správně. Chybí hodnoty z tříd „topení“ (−10 až 16) a „chlazení“ (27 až 40).","b":"Není správně. Chybí obě neplatné třídy (pod −10 a nad 40); −1 a 12 navíc patří do stejné třídy.","c":"Není správně. Pokrývá sice všech pět tříd, ale −1 a 12 patří do stejné třídy (topení), sada tedy není minimální.","d":"Je správně. Každá z pěti tříd je pokryta právě jednou hodnotou."},"obecne":"<p>Sylabus 4.2.1: Třídy ekvivalence jsou: pod −10 (neplatná), −10 až 16 (topení), 17 až 26 (bez zásahu), 27 až 40 (chlazení) a nad 40 (neplatná). Hodnoty −11, −1, 18, 27 a 51 pokrývají každou třídu právě jednou.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-17","n":21,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Která z následujících sad testovacích dat dosáhne při použití tříhodnotové analýzy hraničních hodnot 100% pokrytí pro následující řádek kódu (x je celé číslo)?<\/p><p><code>if (x &gt;= 10) then y := 0<\/code><\/p>","m":["<p>8, 9, 10, 11<\/p>","<p>7, 8, 9<\/p>","<p>7, 8, 10, 11<\/p>","<p>9, 10, 11, 12<\/p>"],"ok":[0],"vys":{"a":"Je správně. Hraniční hodnoty jsou 9 a 10; pro 9 testujeme 8, 9, 10 a pro 10 testujeme 9, 10, 11 – dohromady 8, 9, 10, 11.","b":"Není správně. Chybí hodnoty 10 a 11, hranice 10 tedy není pokryta.","c":"Není správně. Chybí hraniční hodnota 9; hodnota 7 položkou pokrytí není.","d":"Není správně. Chybí hodnota 8 (soused hraniční hodnoty 9); hodnota 12 položkou pokrytí není."},"obecne":"<p>Je-li x větší nebo rovno 10, proměnné y se přiřadí nula. Je-li x menší než 10, proměnné y se nula nepřiřadí.<\/p><p>Hraničními hodnotami systému jsou tedy 9 a&nbsp;10.<\/p><p>Pro 9 budeme testovat hodnoty 8, 9, 10. Pro 10 budeme testovat hodnoty 9, 10, 11. Výsledná sada je tedy 8, 9, 10, 11.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-66","n":22,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Půjčovna aut rozhoduje o zapůjčení vozu podle této rozhodovací tabulky (A = ano, N = ne, „–“ = na hodnotě podmínky nezáleží):<\/p><table><thead><tr><th><\/th><th>Pravidlo 1<\/th><th>Pravidlo 2<\/th><th>Pravidlo 3<\/th><th>Pravidlo 4<\/th><\/tr><\/thead><tbody><tr><td><strong>Podmínky<\/strong><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Věk nad 20 let?<\/td><td>N<\/td><td>A<\/td><td>A<\/td><td>A<\/td><\/tr><tr><td>Čistý řidičský záznam?<\/td><td>–<\/td><td>N<\/td><td>A<\/td><td>A<\/td><\/tr><tr><td>Služební cesta?<\/td><td>–<\/td><td>–<\/td><td>N<\/td><td>A<\/td><\/tr><tr><td><strong>Akce<\/strong><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Půjčit auto?<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>A<\/td><\/tr><tr><td>Účtovat příplatek?<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><\/tr><\/tbody><\/table><p>Jaký je očekávaný výsledek pro tyto testovací případy?<\/p><p>TC1: 26letý zákazník na služební cestě, který má v řidičském záznamu přestupky nebo nehody<\/p><p>TC2: 62letý turista s čistým řidičským záznamem<\/p>","m":["<p>TC1: auto nepůjčit; TC2: půjčit auto s příplatkem<\/p>","<p>TC1: auto nepůjčit; TC2: půjčit auto bez příplatku<\/p>","<p>TC1: půjčit auto s příplatkem; TC2: půjčit auto bez příplatku<\/p>","<p>TC1: půjčit auto s příplatkem; TC2: auto nepůjčit<\/p>"],"ok":[1],"vys":{"a":"Není správně. TC2 není na služební cestě, odpovídá tedy pravidlu 3, které příplatek neúčtuje.","b":"Je správně. TC1 (nad 20 let, záznam není čistý) odpovídá pravidlu 2 – auto nepůjčit; TC2 (nad 20 let, čistý záznam, není na služební cestě) odpovídá pravidlu 3 – půjčit bez příplatku.","c":"Není správně. TC1 nemá čistý řidičský záznam, odpovídá tedy pravidlu 2 a auto se mu nepůjčí, i když je na služební cestě.","d":"Není správně. Oba výsledky jsou opačně: TC1 odpovídá pravidlu 2 (nepůjčit) a TC2 pravidlu 3 (půjčit bez příplatku)."},"obecne":"<p>Sylabus 4.2.3: pro každý testovací případ se najde pravidlo, jehož podmínky odpovídají vstupům, a očekávaný výsledek se převezme z akcí tohoto pravidla; „–“ znamená, že na hodnotě podmínky nezáleží. TC1 (26 let, záznam není čistý) odpovídá pravidlu 2 – auto nepůjčit. TC2 (62 let, čistý záznam, turista) odpovídá pravidlu 3 – půjčit auto bez příplatku.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UP-5-23","n":23,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový diagram systému má tři stavy S1, S2 a S3 a tyto platné přechody: S1 –a→ S2, S2 –b→ S1, S2 –c→ S3, S3 –d→ S2 a S3 –e→ S1. Neplatné přechody diagram nezobrazuje.<\/p><p>Tester navrhl tyto testovací případy:<\/p><table><tr><th>Testovací případ<\/th><th>Výchozí stav<\/th><th>Událost<\/th><th>Očekávaný stav<\/th><\/tr><tr><td>TC1<\/td><td>S1<\/td><td>a<\/td><td>S2<\/td><\/tr><tr><td>TC2<\/td><td>S2<\/td><td>b<\/td><td>S1<\/td><\/tr><tr><td>TC3<\/td><td>S2<\/td><td>c<\/td><td>S3<\/td><\/tr><tr><td>TC4<\/td><td>S3<\/td><td>d<\/td><td>S2<\/td><\/tr><tr><td>TC5<\/td><td>S3<\/td><td>e<\/td><td>S1<\/td><\/tr><\/table><p>Které z následujících tvrzení o těchto testovacích případech je PRAVDIVÉ?<\/p>","m":["<p>Testovací případy pokrývají jen některé z platných přechodů stavového diagramu.<\/p>","<p>Testovací případy nepokrývají všechny stavy stavového diagramu.<\/p>","<p>Testovací případy pokrývají všechny platné přechody stavového diagramu.<\/p>","<p>Testovací případy pokrývají platné i neplatné přechody stavového diagramu.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Pokryty jsou všechny platné přechody.","b":"Není správně. Testy navštíví všechny tři stavy; 100% pokrytí platných přechodů zaručuje i 100% pokrytí všech stavů.","c":"Je správně. Pět testů pokrývá všech pět platných přechodů, tedy 100% pokrytí platných přechodů.","d":"Není správně. Žádný z testů se nepokouší o neplatný přechod."},"obecne":"<p>Sylabus 4.2.4: Testy pokrývají všech pět platných přechodů (S1 → S2, S2 → S1, S2 → S3, S3 → S2, S3 → S1), dosahují tedy 100% pokrytí platných přechodů a tím i všech stavů. Neplatné přechody netestují, takže nedosahují 100% pokrytí všech přechodů.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-74","n":24,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Testujete modul kódu. Jak určíte dosažené pokrytí větví?<\/p>","m":["<p>Vezmete počet otestovaných větví a vydělíte jej celkovým počtem spustitelných příkazů v modulu<\/p>","<p>Vezmete počet otestovaných větví a vydělíte jej celkovým počtem rozhodnutí v modulu<\/p>","<p>Vezmete počet otestovaných rozhodnutí a vydělíte jej celkovým počtem řádků kódu v modulu<\/p>","<p>Vezmete počet otestovaných větví a vydělíte jej celkovým počtem podmíněných a nepodmíněných větví v modulu<\/p>"],"ok":[3],"vys":{"a":"Není správně. Pokrytí větví se počítá vzhledem k celkovému počtu větví, nikoli spustitelných příkazů.","b":"Není správně. Jmenovatelem je celkový počet větví, nikoli počet rozhodnutí.","c":"Není správně. Pokrytí větví nesouvisí s počtem řádků kódu.","d":"Je správně. Pokrytí větví je počet větví pokrytých testy vydělený celkovým počtem podmíněných i nepodmíněných větví."},"obecne":"<p><strong>Podle sylabu (kap. 4.3.2):<\/strong> Při testování větví jsou položkami pokrytí větve a cílem je navrhovat testovací případy tak, aby došlo k pokrytí větví v určité části kódu při definované akceptovatelné úrovni pokrytí. <strong>Pokrytí se měří jako počet větví pokrytých testy k celkovému počtu větví (obvykle vyjádřeno v procentech).<\/strong><\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UC-4-68","n":25,"lo":"FL-4.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co znamená, že sada testů dosáhla 90% pokrytí příkazů?<\/p>","m":["<p>Touto sadou testů bylo prověřeno 9 z každých 10 spustitelných příkazů<\/p>","<p>Na tomto softwaru bylo spuštěno 9 z každých 10 testů<\/p>","<p>Touto sadou testů bylo prověřeno 9 z každých 10 výsledků rozhodnutí<\/p>","<p>Touto sadou testů bylo prověřeno 9 z každých 10 větví<\/p>"],"ok":[0],"vys":{"a":"Je správně. Pokrytí příkazů je podíl spustitelných příkazů provedených testy ze všech spustitelných příkazů.","b":"Není správně. Podíl spuštěných testů je metrika provedení testů, nikoli pokrytí kódu.","c":"Není správně. Výsledky rozhodnutí souvisejí s pokrytím větví, nikoli příkazů.","d":"Není správně. Podíl pokrytých větví je pokrytí větví, nikoli příkazů."},"obecne":"Sylabus 4.3.1: při testování příkazů jsou položkami pokrytí spustitelné příkazy a pokrytí se měří jako podíl spustitelných příkazů pokrytých testy ze všech spustitelných příkazů. 90% pokrytí příkazů tedy znamená, že bylo provedeno 9 z každých 10 spustitelných příkazů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"}},{"id":"UC-4-26","n":26,"lo":"FL-4.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Tester testuje proces dokončení objednávky na webu e-shopu. Pokusí se pokračovat s prázdným nákupním košíkem a systém mu neočekávaně umožní přejít na platební stránku.<\/p><p>Tento test navrhl proto, že si vzpomněl na dřívější projekty, v nichž vývojáři zapomněli implementovat kontrolu prázdného košíku.<\/p><p>Jakou techniku testování tester použil?<\/p>","m":["<p>Testování založené na kontrolních seznamech<\/p>","<p>Odhadování chyb<\/p>","<p>Testování přechodů stavů<\/p>","<p>Průzkumné testování<\/p>"],"ok":[1],"vys":{"a":"Není správně. Tester nepostupoval podle kontrolního seznamu testovacích podmínek.","b":"Je správně. Test vychází ze znalosti typických chyb vývojářů z minulosti, což je podstata odhadování chyb.","c":"Není správně. Test nebyl odvozen ze stavového modelu systému, ale ze zkušenosti testera.","d":"Není správně. U průzkumného testování se testy navrhují, provádějí a vyhodnocují současně s učením o testovaném objektu; zde tester cíleně využil znalost typické chyby vývojářů."},"obecne":"Sylabus 4.4.1: odhadování chyb předvídá výskyt chyb, defektů a selhání na základě znalostí testera, např. typických chyb vývojářů a defektů, které z nich vznikají. Tester zde cíleně otestoval situaci, o níž ví, že ji vývojáři často opomíjejí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"}},{"id":"UP-6-27","n":27,"lo":"FL-4.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Jaký je hlavní účel testování založeného na kontrolních seznamech?<\/p>","m":["<p>Zlepšit uživatelský zážitek z aplikace<\/p>","<p>Zajistit, aby byly provedeny všechny testovací případy<\/p>","<p>Poskytnout vodítko a určitou míru konzistence při testování<\/p>","<p>Automatizovat provedení testů<\/p>"],"ok":[2],"vys":{"a":"Není správně. Kontrolní seznam se může týkat i použitelnosti, ale zlepšování uživatelského zážitku není jeho hlavním účelem.","b":"Není správně. Kontrolní seznam obsahuje testovací podmínky, nikoli seznam testovacích případů k provedení.","c":"Je správně. Při absenci podrobných testovacích případů může testování založené na kontrolních seznamech poskytnout vodítko pro testování a zajistit určitou míru konzistence.","d":"Není správně. Testování založené na kontrolních seznamech je technika založená na zkušenostech; jeho cílem není automatizace. Položky ověřitelné automaticky do kontrolního seznamu dokonce nepatří."},"obecne":"Sylabus 4.4.3: testeři navrhují, implementují a provádějí testy tak, aby pokryli testovací podmínky z kontrolního seznamu. Při absenci podrobných testovacích případů poskytuje tato technika vodítko pro testování a zajišťuje určitou míru konzistence.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.3","nazev":"Testování založené na kontrolních seznamech","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-tri-testovani-zalozene-na-kontrolnich-seznamech"}},{"id":"UP-2-28","n":28,"lo":"FL-4.5.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících akceptačních kritérií je zapsáno ve formátu orientovaném na scénáře?<\/p>","m":["<p>Systém zvládne 1 000 současně přihlášených uživatelů bez pádu.<\/p>","<p>Uživatel si může obnovit heslo zodpovězením bezpečnostních otázek.<\/p>","<p>Překročí-li uživatel maximální počet pokusů o přihlášení, účet se dočasně zablokuje.<\/p>","<p>Za předpokladu, že uživatel vyplnil formulář, když klikne na „Odeslat“, pak se zobrazí potvrzení.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Jde o výkonnostní požadavek zapsaný jako pravidlo, ne o scénář.","b":"Není správně. Jde o funkcionální pravidlo bez struktury scénáře (výchozí stav – akce – výsledek).","c":"Není správně. Jde o byznys pravidlo, typickou položku kritérií orientovaných na pravidla.","d":"Je správně. Kritérium popisuje scénář ve formátu Given/When/Then (za předpokladu – když – pak), typickém pro BDD."},"obecne":"<p>Sylabus 4.5.2: Dva nejběžnější formáty akceptačních kritérií jsou orientovaný na scénáře (např. formát Given/When/Then používaný v BDD) a orientovaný na pravidla (např. verifikační seznam s odrážkami nebo tabulka mapování vstupů a výstupů).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"}},{"id":"UC-4-41","n":29,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Uvažujte následující uživatelský scénář:<\/p><p><em>Jako student Nezam Academy chci vyplňovat kvízy online, abych mohl posoudit, jak rozumím studijní látce, a sledovat svůj pokrok.<\/em><\/p><p>Akceptační kritéria:<\/p><ol><li><strong>Přístup ke kvízu:<\/strong><ul><li>Studenti musí mít možnost otevřít kvíz přímo ze svého přehledu kurzu.<\/li><li>Kvíz by měli mít možnost vyplnit pouze studenti zapsaní do kurzu.<\/li><\/ul><\/li><li><strong>Obsah kvízu:<\/strong><ul><li>Kvíz musí obsahovat otázky s výběrem z možností, otázky typu pravda/nepravda a otázky s krátkou odpovědí.<\/li><li>Každý kvíz musí mít název, popis a jasné pokyny, jak jej vyplnit.<\/li><\/ul><\/li><li><strong>Navigace mezi otázkami:<\/strong><ul><li>Studenti musí mít možnost přecházet mezi otázkami v rámci kvízu.<\/li><li>Indikátor průběhu musí zobrazovat počet zodpovězených a zbývajících otázek.<\/li><\/ul><\/li><li><strong>Časovač:<\/strong><ul><li>Na obrazovce by měl být zobrazen časovač ukazující zbývající čas na dokončení kvízu.<\/li><li>Časovač se musí spustit, když student začne kvíz, a zastavit se, když je kvíz odeslán.<\/li><\/ul><\/li><\/ol><p>Který z následujících testovacích případů NENÍ platným testovacím případem ATDD pro tento uživatelský scénář?<\/p>","m":["<p>Zopakovat kvíz poté, co student nedosáhl potřebného počtu bodů pro úspěšné složení<\/p>","<p>Otevřít přehled kurzu a přejít na stránku s kvízy<\/p>","<p>Přečíst si pokyny vztahující se ke kvízu<\/p>","<p>V kvízu s 10 otázkami přejít na otázku 10 a poté se vrátit na otázku 1<\/p>"],"ok":[0],"vys":{"a":"Je správně. Opakování kvízu po neúspěchu nepokrývá žádné akceptační kritérium; test by přesahoval rámec uživatelského scénáře.","b":"Není správně. Test odpovídá kritériu Přístup ke kvízu – otevření kvízu z přehledu kurzu.","c":"Není správně. Test odpovídá kritériu Obsah kvízu – každý kvíz musí mít jasné pokyny.","d":"Není správně. Test odpovídá kritériu Navigace mezi otázkami."},"obecne":"Sylabus 4.5.3: v ATDD se testovací případy odvozují z akceptačních kritérií; musí pokrývat všechny charakteristiky uživatelského scénáře a neměly by přesahovat jeho rámec. Opakování kvízu po neúspěchu žádné kritérium nepožaduje – může být předmětem jiného uživatelského scénáře.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UP-5-33","n":30,"lo":"FL-5.1.6","k":"K1","k3":true,"vyber":1,"q":"<p>Co v kontextu testovací pyramidy znamená pojem „granularita testů“?<\/p>","m":["<p>Hloubku dosaženého pokrytí testy.<\/p>","<p>Rozsah nebo velikost testovaných jednotek.<\/p>","<p>Míru podrobnosti testovací dokumentace.<\/p>","<p>Míru, do jaké testy interagují s externími systémy.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Pokrytí vyjadřuje, do jaké míry testy pokrývají kód nebo požadavky, nikoli granularitu jednotlivých testů.","b":"Je správně. Granularita vyjadřuje rozsah testované části: testy ve spodní vrstvě pyramidy jsou malé a ověřují malou část funkcionality, E2E testy v horní vrstvě velkou část.","c":"Není správně. Podrobnost testovací dokumentace s granularitou testů nesouvisí.","d":"Není správně. Míra závislosti na dalších částech systému odpovídá izolaci testů, což je v pyramidě samostatná vlastnost."},"obecne":"Sylabus 5.1.6: Testovací pyramida ukazuje, že různé testy mohou mít různou granularitu. Čím vyšší vrstva, tím nižší granularita (test ověřuje větší část funkcionality), menší izolace a delší doba provádění testu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.6","nazev":"Testovací pyramida","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sest-testovaci-pyramida"}},{"id":"UC-5-19","n":31,"lo":"FL-5.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Následující úryvky pocházejí z různých částí plánu testování.<\/p><p><em>i. Rozpočet na testování tohoto projektu byl stanoven na 50 000 USD. Tento rozpočet pokryje náklady na hardware, softwarové licence, zdroje pro testování a další výdaje související s testováním. Jakékoli výdaje přesahující přidělený rozpočet vyžadují schválení projektovým manažerem.<\/em><\/p><p><em>ii.<\/em><\/p><ul><li><em>Všechny kritické defekty byly opraveny a ověřeny.<\/em><\/li><li><em>Nezůstávají otevřené žádné defekty s vysokou prioritou.<\/em><\/li><li><em>Všechny testovací případy byly úspěšně provedeny.<\/em><\/li><li><em>Bylo dosaženo pokrytí testy alespoň 95 %.<\/em><\/li><\/ul><p>Do kterých částí plánu testování tyto úryvky patří?<\/p>","m":["<p>i patří do rozpočtu a harmonogramu, ii do kontextu testování.<\/p>","<p>i patří do předpokladů a omezení, ii do rozpočtu a harmonogramu.<\/p>","<p>i patří do rozpočtu a harmonogramu, ii do přístupu k testování.<\/p>","<p>i patří do kontextu testování, ii do přístupu k testování.<\/p>"],"ok":[2],"vys":{},"obecne":"Sylabus 5.1.1: Plán testování obsahuje mj. část rozpočet a harmonogram (sem patří úryvek i) a přístup k testování, který zahrnuje mimo jiné vstupní a výstupní kritéria. Úryvek ii je seznam výstupních kritérií (opravené kritické defekty, žádné otevřené defekty s vysokou prioritou, provedení testů, dosažené pokrytí), patří tedy do přístupu k testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"}},{"id":"UC-5-25","n":32,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"<p>Společnost používá k odhadu pracnosti testování svých projektů poměry. V předchozím projektu, který je podobný aktuálně plánovanému projektu, byl poměr pracnosti vývoje k pracnosti testování 2:1. Očekává se, že pracnost vývoje bude 400 člověko-dnů.<\/p><p>Jaká je odhadovaná pracnost testování nového projektu?<\/p>","m":["<p>200 člověkodnů.<\/p>","<p>250 člověkodnů.<\/p>","<p>300 člověkodnů.<\/p>","<p>400 člověkodnů.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Pracnost testování = 400 / 2 = 200 člověkodnů.","b":"Není správně. 250 člověkodnů neodpovídá poměru 2 : 1.","c":"Není správně. 300 člověkodnů by odpovídalo poměru 4 : 3.","d":"Není správně. 400 člověkodnů je pracnost vývoje (poměr 1 : 1), ne testování."},"obecne":"<p>Odhad na základě poměrů (sylabus kap. 5.1.4): pracnost vývoje : pracnost testování = 2 : 1, tedy pracnost testování = 400 / 2 = <strong>200 člověko-dnů<\/strong>. (Obdobně sylabus uvádí příklad: poměr 3:2 a pracnost vývoje 600 člověko-dnů → pracnost testování 400 člověko-dnů.)<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-2-32","n":33,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Máte za úkol uspořádat sadu testovacích případů do testovací procedury, která určí pořadí jejich provedení v e-shopu s knihami. Chcete testovat ucelené transakce od začátku do konce (end-to-end) a zároveň zohlednit prioritu rizika – některé testovací případy jsou kritičtější než jiné (1 = nejvyšší riziko). Testovací případ lze spustit, jen pokud v téže transakci před ním proběhl test typu, na kterém závisí; kvůli další transakci lze testovací případ spustit opakovaně.<\/p><table><thead><tr><th>Testovací případ<\/th><th>Typ testu<\/th><th>Priorita rizika<\/th><th>Závisí na typu testu<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>Procházení<\/td><td>2<\/td><td>–<\/td><\/tr><tr><td>2<\/td><td>Výběr<\/td><td>3<\/td><td>Procházení<\/td><\/tr><tr><td>3<\/td><td>Výběr<\/td><td>2<\/td><td>Procházení<\/td><\/tr><tr><td>4<\/td><td>Nákupní košík<\/td><td>1<\/td><td>Výběr<\/td><\/tr><tr><td>5<\/td><td>Nákupní košík<\/td><td>3<\/td><td>Výběr<\/td><\/tr><tr><td>6<\/td><td>Nákup<\/td><td>1<\/td><td>Nákupní košík<\/td><\/tr><tr><td>7<\/td><td>Vrácení peněz<\/td><td>4<\/td><td>Nákup<\/td><\/tr><\/tbody><\/table><p>Které pořadí provedení NEJLÉPE splňuje oba cíle?<\/p>","m":["<p>1, 3, 4, 6, 1, 2, 5, 6, 7<\/p>","<p>4, 6, 1, 3, 2, 5, 7<\/p>","<p>1, 3, 2, 4, 5, 6, 7<\/p>","<p>1, 2, 5, 6, 7, 1, 3, 4, 6, 7<\/p>"],"ok":[0],"vys":{"a":"Je správně. První transakce 1, 3, 4, 6 co nejdříve pokryje testy s nejvyšším rizikem (4 a 6), druhá transakce 1, 2, 5, 6, 7 doplní zbývající testy.","b":"Není správně. Testy 4 a 6 nelze spustit jako první – nejprve musí proběhnout procházení, výběr a (pro test 6) nákupní košík.","c":"Není správně. Závislosti jsou sice dodrženy, ale před nejrizikovější testy 4 a 6 se zařazují méně rizikové testy 2 a 5 a transakce nejsou ucelené.","d":"Není správně. Závislosti jsou dodrženy, ale nejrizikovější testy 4 a 6 se provádějí až ve druhé transakci."},"obecne":"<p>Sylabus 5.1.5: Testovací případy se řadí podle priority (zde rizika) s ohledem na závislosti. Nejrizikovější jsou testy 4 a 6; test 6 vyžaduje nákupní košík (4), ten výběr (3 má vyšší prioritu než 2) a ten procházení (1). První transakce je tedy 1, 3, 4, 6. Zbývající testy 2, 5 a 7 pokryje druhá transakce 1, 2, 5, 6, 7 (vrácení peněz vyžaduje předchozí nákup).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"TR-063","n":34,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"Co představují testovací kvadranty?","m":["Čtyři úrovně testování od testování komponent po akceptační testování","Třídění testů podle zaměření (byznys/technologie) a účelu (podpora týmu/kritika produktu)","Model pro odhad pracnosti testování podle velikosti a složitosti produktu","Čtyři po sobě jdoucí fáze procesu testování od analýzy po dokončení"],"ok":[1],"vys":{"a":"Není správně. Kvadranty nejsou úrovně testování; dávají úrovně testování do souvislosti s typy testů.","b":"Je správně. Osa Y odlišuje testy zaměřené na byznys a na technologii, osa X testy podporující tým a testy kritizující produkt.","c":"Není správně. Pro odhad pracnosti slouží techniky odhadování (např. tříbodový odhad), ne testovací kvadranty.","d":"Není správně. Kvadranty nepopisují fáze procesu testování, ale seskupují typy a úrovně testů."},"obecne":"Sylabus 5.1.7: Testovací kvadranty dávají do souvislosti úrovně testování s typy testů, činnostmi, technikami a pracovními produkty v agilním vývoji. Kombinace os (byznys/technologie, podpora týmu/kritika produktu) určuje kvadranty Q1–Q4.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"UP-4-34","n":35,"lo":"FL-5.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Pracujete jako tester na projektu vývoje pokladního systému (point-of-sale) pro obchody s potravinami a další podobné maloobchodní prodejny. Která z následujících možností je pro takový projekt produktovým rizikem?<\/p>","m":["<p>Uvedení spolehlivějšího konkurenčního produktu na trh.<\/p>","<p>Dodání neúplného vydání pro testování do prvního cyklu systémového testování.<\/p>","<p>Systém nepřijme povolené platební karty.<\/p>","<p>Při konfirmačním testování selže nadměrně vysoký počet oprav defektů.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Příchod konkurenčního produktu je vnější obchodní riziko, netýká se kvalitativních charakteristik vyvíjeného produktu.","b":"Není správně. Zpožděné nebo neúplné dodávky pracovních produktů jsou organizační problém, tedy projektové riziko.","c":"Je správně. Nepřijetí povolených platebních karet je chybějící nebo nesprávná funkcionalita, tedy produktové riziko.","d":"Není správně. Vysoký počet neúspěšných oprav ohrožuje harmonogram a rozpočet projektu – jde o projektové riziko."},"obecne":"Sylabus 5.2.2: Produktová rizika souvisejí s kvalitativními charakteristikami produktu (např. chybějící nebo nesprávná funkcionalita), projektová rizika s managementem a řízením projektu (organizační, lidské, technické a dodavatelské problémy). Nepřijetí povolených platebních karet je selhání funkcionality systému, proto jde o produktové riziko.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.2.2","nazev":"Projektová a produktová rizika","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-dva-projektova-a-produktova-rizika"}},{"id":"UP-5-36","n":36,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících položek NENÍ obsažena v souhrnném reportu z testování?<\/p>","m":["<p>Vyhodnocení skutečného postupu vůči výstupním kritériím.<\/p>","<p>Odchylky od plánu testování.<\/p>","<p>Vyhodnocení kvality testovaného produktu.<\/p>","<p>Definice kritérií úspěšnosti/neúspěšnosti a cílů testování.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Souhrnný report obsahuje vyhodnocení testování na základě původního plánu testování, tj. vůči cílům testování a výstupním kritériím.","b":"Není správně. Odchylky od plánu testování (např. od harmonogramu, trvání a pracnosti) jsou typickým obsahem souhrnného reportu z testování.","c":"Není správně. Vyhodnocení kvality produktu je typickým obsahem souhrnného reportu z testování.","d":"Je správně. Cíle testování a kritéria se definují už při plánování testování (v plánu testování); souhrnný report z testování je pouze vyhodnocuje."},"obecne":"Sylabus 5.3.2: Souhrnný report z testování obsahuje mj. shrnutí testů, vyhodnocení testování a kvality produktu na základě původního plánu testování (cílů testování a výstupních kritérií), odchylky od plánu testování, neošetřená rizika a nevyřešené defekty a ponaučení. Definice cílů a kritérií patří do plánu testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UP-2-37","n":37,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co by systém pro konfigurační management obvykle NEPOSKYTOVAL?<\/p>","m":["Porovnání výsledků testů s očekávanými výsledky","Propojení požadavků zákazníka s čísly verzí","Omezený přístup ke knihovně zdrojového kódu","Přesné rozdíly mezi verzemi zdrojového kódu komponent"],"ok":[0],"vys":{"a":"Je správně. Porovnání skutečných a očekávaných výsledků zajišťují nástroje pro provedení testů, ne konfigurační management.","b":"Není správně. Zaznamenávání vztahů mezi konfiguračními položkami a jejich verzemi je úkolem konfiguračního managementu.","c":"Není správně. Řízení přístupu a změn ke konfiguračním položkám je součástí konfiguračního managementu.","d":"Není správně. Evidence verzí a změn mezi nimi je základní funkcí konfiguračního managementu."},"obecne":"Sylabus 5.4: Konfigurační management slouží k identifikaci, řízení a sledování pracovních produktů – eviduje verze, změny, vztahy mezi položkami a baseline. Porovnávání výsledků testů s očekávanými výsledky k jeho úkolům nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"UP-2-38","n":38,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Pracujete jako tester na systému internetového bankovnictví. Dostupnost je považována za jedno z hlavních produktových rizik (rizik kvality) systému. Najdete reprodukovatelné selhání, při kterém zákazníci při převodu prostředků mezi běžnými typy účtů ztratí spojení s webem banky a po dobu tří až pěti minut se nemohou znovu připojit.<\/p><p>Které z následujících shrnutí by bylo vhodné pro report o defektu k tomuto selhání, tedy takové, které vystihuje jak podstatu selhání, tak jeho dopad na zainteresované strany?<\/p>","m":["Vývojáři zanesli závažný defekt dostupnosti, který naše zákazníky vážně rozladí","Běžný převod mezi účty ukončí relaci zákazníka a opětovné připojení je několik minut nemožné","Protokoly webového serveru ukazují při testu 07.005 chybu 0x44AB27, která není očekávaným hlášením v /tmp","Výkonnost je nízká a spolehlivost pod zátěží je nestabilní"],"ok":[1],"vys":{"a":"Není správně. Shrnutí nepopisuje konkrétní selhání a obviňuje vývojáře, což komunikaci s nimi poškozuje.","b":"Je správně. Shrnutí věcně popisuje konkrétní selhání (ukončení relace při převodu) i jeho dopad na zákazníky (nedostupnost).","c":"Není správně. Technické detaily jsou užitečné pro vývojáře, ale shrnutí nepopisuje selhání ani jeho dopad na zainteresované strany.","d":"Není správně. Shrnutí je příliš vágní – nepopisuje konkrétní selhání ani situaci, kdy nastává."},"obecne":"Sylabus 5.5: Název reportu o defektu má obsahovat krátké shrnutí reportované anomálie a report má uvádět závažnost, tj. dopad na zájmy zainteresovaných stran. Dobré shrnutí popisuje konkrétní pozorované selhání a jeho dopad, je věcné a nikoho neobviňuje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UC-6-05","n":39,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jak se nazývají nástroje, které usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur?<\/p>","m":["<p>Nástroje pro provádění testů a měření pokrytí<\/p>","<p>Nástroje pro management testování<\/p>","<p>Nástroje pro návrh a implementaci testů<\/p>","<p>Nástroje pro statické testování<\/p>"],"ok":[2],"vys":{"a":"Není správně. Nástroje pro provádění testů a měření pokrytí testy spouštějí, nevytvářejí.","b":"Není správně. Nástroje pro management testování usnadňují správu SDLC, požadavků, testů, defektů a konfigurací.","c":"Je správně. Nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, dat a procedur.","d":"Není správně. Nástroje pro statické testování podporují revize a statickou analýzu."},"obecne":"Sylabus 6.1: nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-4-40","n":40,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je možným rizikem používání nástrojů pro automatizaci testů?<\/p>","m":["<p>Nástroj zopakuje přesně totéž, co provedl při minulém spuštění.<\/p>","<p>Nedostatečné spoléhání na nástroj, tj. pokračování v manuálním testování i po pořízení nástroje.<\/p>","<p>Objektivnější hodnocení, např. měření pokrytí.<\/p>","<p>Nerealistická očekávání, tj. očekávání, že nástroj zvládne příliš mnoho.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Opakování stejných kroků je žádoucí konzistence a opakovatelnost, tedy přínos.","b":"Není správně. Rizikem je naopak přílišné spoléhání na nástroj; manuální testování má automatizaci doplňovat.","c":"Není správně. Objektivnější hodnocení je přínosem automatizace.","d":"Je správně. Nerealistická očekávání ohledně přínosů nástroje jsou rizikem automatizace."},"obecne":"Sylabus 6.2 uvádí mezi riziky automatizace testů nerealistická očekávání ohledně přínosů nástroje (včetně funkcionality a snadnosti použití) a přílišné spoléhání na nástroj.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}}]};
